// Package api_test holds the contract tests that read the committed OpenAPI
// document, which is the one artifact that knows every mounted route.
package api_test

import (
	"encoding/json"
	"os"
	"sort"
	"strings"
	"testing"

	"github.com/therealmcsparrow/mcharbor/core/rbac"
)

// specFile is regenerated by booting the server with MCHARBOR_EMIT_OPENAPI set;
// CI rewrites it and fails on a diff, so these tests always read the live router.
// It is a var, not a const, so a detector self-test can point it at a temp copy
// instead of mutating the committed spec to prove a check can fail.
var specFile = "openapi.json"

// minOperations guards against a truncated or half-generated document passing
// every assertion by containing nothing to assert about.
const minOperations = 400

type permissionGate struct {
	Scope string   `json:"scope"`
	Keys  []string `json:"keys"`
	Match string   `json:"match"`
	// EnvParam is the path parameter rbac.PinEnvToPath scopes this gate to.
	EnvParam string `json:"env_param"`
}

type operation struct {
	OperationID string           `json:"operationId"`
	Security    []map[string]any `json:"security"`
	Permission  []permissionGate `json:"x-mcharbor-permission"`
	Exempt      string           `json:"x-mcharbor-exempt"`
}

type specOp struct {
	Method string
	Path   string
	Op     operation
}

func (s specOp) String() string { return s.Method + " " + s.Path + " (" + s.Op.OperationID + ")" }

func (s specOp) mutating() bool {
	switch s.Method {
	case "POST", "PUT", "PATCH", "DELETE":
		return true
	}
	return false
}

func loadOperations(t *testing.T) []specOp {
	t.Helper()
	raw, err := os.ReadFile(specFile)
	if err != nil {
		t.Fatalf("read %s: %v", specFile, err)
	}
	var doc struct {
		Paths map[string]map[string]json.RawMessage `json:"paths"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("parse %s: %v", specFile, err)
	}

	var ops []specOp
	for path, item := range doc.Paths {
		for method, body := range item {
			if method == "parameters" {
				continue
			}
			var op operation
			if err := json.Unmarshal(body, &op); err != nil {
				t.Fatalf("parse %s %s: %v", method, path, err)
			}
			ops = append(ops, specOp{Method: strings.ToUpper(method), Path: path, Op: op})
		}
	}
	sort.Slice(ops, func(i, j int) bool { return ops[i].String() < ops[j].String() })
	if len(ops) < minOperations {
		t.Fatalf("%s holds %d operations, fewer than %d; regenerate it rather than trusting an empty scan",
			specFile, len(ops), minOperations)
	}
	return ops
}

// TestEveryMutatingOperationIsGatedOrExempt is layer 5 of the permission
// lifecycle: a mutating route carries a permission gate or a written reason.
func TestEveryMutatingOperationIsGatedOrExempt(t *testing.T) {
	var missing []string
	for _, s := range loadOperations(t) {
		if !s.mutating() {
			continue
		}
		if len(s.Op.Permission) == 0 && strings.TrimSpace(s.Op.Exempt) == "" {
			missing = append(missing, s.String())
		}
	}
	if len(missing) > 0 {
		t.Errorf("%d mutating operations carry neither a RequirePermission gate nor apispec.Exempt(reason).\n"+
			"Add the permission in routes.go, or, when the route is self-service or pre-auth, state why:\n  %s",
			len(missing), strings.Join(missing, "\n  "))
	}
}

// TestEveryGatedKeyIsInTheCatalog catches a gate naming a key no role can be
// granted, which denies everyone while looking governed.
func TestEveryGatedKeyIsInTheCatalog(t *testing.T) {
	catalog := make(map[string]bool)
	for _, e := range rbac.CatalogSeed() {
		catalog[string(e.Key)] = true
	}
	var unknown []string
	for _, s := range loadOperations(t) {
		for _, gate := range s.Op.Permission {
			for _, key := range gate.Keys {
				if !catalog[key] {
					unknown = append(unknown, s.String()+" -> "+key)
				}
			}
		}
	}
	if len(unknown) > 0 {
		t.Errorf("operations gated on keys absent from CatalogSeed():\n  %s", strings.Join(unknown, "\n  "))
	}
}

// TestProtectedOperationsDeclareSecurity keeps the band a route was mounted in
// visible to generated clients, which decide from it whether to send credentials.
func TestProtectedOperationsDeclareSecurity(t *testing.T) {
	var bad []string
	for _, s := range loadOperations(t) {
		if len(s.Op.Permission) > 0 && len(s.Op.Security) == 0 {
			bad = append(bad, s.String())
		}
	}
	if len(bad) > 0 {
		t.Errorf("permission-gated operations with no security requirement:\n  %s", strings.Join(bad, "\n  "))
	}
}

// pluginCatchAll is the one deliberate escape hatch: plugin routes are
// registered at runtime and dispatched through /api, behind PluginPermissionMiddleware.
const pluginCatchAll = "/api"

// TestOnlyThePluginCatchAllIsUnrecorded keeps routes from being mounted through
// Mux(), which would hide them from the document and from every test above.
func TestOnlyThePluginCatchAllIsUnrecorded(t *testing.T) {
	raw, err := os.ReadFile("unrecorded-routes.txt")
	if err != nil {
		t.Fatalf("read unrecorded-routes.txt: %v", err)
	}
	var escaped []string
	for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, " ", 2)
		if len(parts) != 2 || parts[1] != pluginCatchAll {
			escaped = append(escaped, line)
		}
	}
	if len(escaped) > 0 {
		t.Errorf("routes served by the router but never recorded in the spec; register them through "+
			"*apispec.Router instead of Mux():\n  %s", strings.Join(escaped, "\n  "))
	}
}

// TestExportsRequireTheirExportKey guards the audit log's signed export: it was
// gated on audit.view, which left the audit.export key protecting nothing.
func TestExportsRequireTheirExportKey(t *testing.T) {
	want := map[string]string{
		"GET /api/audit/export":          "audit.export",
		"GET /api/audit/coverage/export": "audit.export",
	}
	for _, op := range loadOperations(t) {
		key, ok := want[op.Method+" "+op.Path]
		if !ok {
			continue
		}
		delete(want, op.Method+" "+op.Path)
		found := false
		for _, gate := range op.Op.Permission {
			for _, k := range gate.Keys {
				if k == key {
					found = true
				}
			}
		}
		if !found {
			t.Errorf("%s is not gated on %s: %+v", op, key, op.Op.Permission)
		}
	}
	for route := range want {
		t.Errorf("%s is missing from the spec", route)
	}
}

// TestWorkflowReadsRequireWorkflowsView guards the workflow reads, which ran
// ungated while the sidebar already hid the page from roles without the key.
func TestWorkflowReadsRequireWorkflowsView(t *testing.T) {
	want := map[string]bool{
		"GET /api/workflows": true, "GET /api/workflows/runs": true, "GET /api/workflows/link-outputs": true,
		"GET /api/workflows/{id}": true, "GET /api/workflows/{id}/export": true, "GET /api/workflows/{id}/live": true,
	}
	for _, op := range loadOperations(t) {
		if !want[op.Method+" "+op.Path] {
			continue
		}
		delete(want, op.Method+" "+op.Path)
		found := false
		for _, gate := range op.Op.Permission {
			for _, k := range gate.Keys {
				found = found || k == "workflows.view"
			}
		}
		if !found {
			t.Errorf("%s is not gated on workflows.view: %+v", op, op.Op.Permission)
		}
	}
	for route := range want {
		t.Errorf("%s is missing from the spec", route)
	}
}
